      "unit": "",
      "hint": "Sai phân triệt tiêu (Telescoping Series).",
      "solution": "**Phương pháp: Sai phân triệt tiêu (Telescoping Series).**\n\n- Nhận xét khoảng cách giữa hai thừa số ở mỗi mẫu số là: 5 – 2 = 8 – 5 = ... = 3.\n- Áp dụng công thức sai phân: k / [n × (n + k)] = 1/n – 1/(n + k).\n- Nhân cả biểu thức với 3, ta có:\n  3 × S = 3/(2×5) + 3/(5×8) + 3/(8×11) + ... + 3/(29×32)\n  3 × S = (1/2 – 1/5) + (1/5 – 1/8) + (1/8 – 1/11) + ... + (1/29 – 1/32)\n- Các phân số ở giữa triệt tiêu lẫn nhau từng đôi một:\n  3 × S = 1/2 – 1/32 = 16/32 – 1/32 = 15/32\n- Suy ra:\n  S = (15/32) : 3 = 5/32.\n\n**Đáp số: 5/32.**"
