      "solution": "**Phương pháp: Chuyển đổi số thập phân tuần hoàn thành phân số tối giản.**\n\n- Đặt x = 0.1454545...\n- Chu kỳ tuần hoàn gồm 2 chữ số (45) và phần bất thường gồm 1 chữ số (1):\n  + Nhân x với 10: 10x = 1.454545...\n  + Nhân x với 1000: 1000x = 145.454545...\n- Lấy biểu thức dưới trừ biểu thức trên để triệt tiêu toàn bộ phần thập phân tuần hoàn:\n  1000x – 10x = 145.454545... – 1.454545...\n  990x = 144\n  x = 144 / 990\n- Rút gọn phân số bằng cách chia cả tử và mẫu cho ƯCLN(144, 990) = 18:\n  144 : 18 = 8\n  990 : 18 = 55\n- Vậy phân số tối giản là 8/55.\n\n**Đáp số: 8/55.**"
