      "questionVi": "Tính tổng: S = 2 + 2² + 2³ + 2⁴ + ... + 2¹⁰.",
      "questionEn": "Find the sum: S = 2 + 2² + 2³ + 2⁴ + ... + 2¹⁰.",
      "image": null,
