      "hint": "Kỹ thuật nhân dồn cơ số tính tổng cấp số nhân.",
      "solution": "**Phương pháp: Kỹ thuật nhân dồn cơ số tính tổng cấp số nhân.**\n\n- Ta có biểu thức: S = 2 + 2² + 2³ + ... + 2¹⁰.\n- Nhân cả hai vế với cơ số 2:\n  2 × S = 2² + 2³ + 2⁴ + ... + 2¹⁰ + 2¹¹.\n- Lấy biểu thức (2 × S) trừ đi biểu thức S:\n  2 × S – S = (2² + 2³ + ... + 2¹¹) – (2 + 2² + ... + 2¹⁰)\n  S = 2¹¹ – 2.\n- Tính giá trị lũy thừa:\n  2¹⁰ = 1024  =>  2¹¹ = 2048.\n- Vậy: S = 2048 – 2 = 2046.\n\n**Đáp số: 2046.**"
