      "solution": "**Phương pháp: Đồng dư thức và chu kỳ số dư modulo 100.**\n\n- Hai chữ số tận cùng của một số chính là số dư của số đó khi chia cho 100.\n- Xét các lũy thừa ban đầu của 7 theo modulo 100:\n  + 7¹ = 07 ≡ 7 (mod 100)\n  + 7² = 49 ≡ 49 (mod 100)\n  + 7³ = 343 ≡ 43 (mod 100)\n  + 7⁴ = 2401 ≡ 01 (mod 100)\n- Vì 7⁴ tận cùng là 01 nên chu kỳ lặp lại hai chữ số tận cùng của lũy thừa cơ số 7 là 4.\n- Chia số mũ 2026 cho chu kỳ 4:\n  2026 = 4 × 506 + 2 (dư 2).\n- Do đó:\n  7²⁰²⁶ = (7⁴)⁵⁰⁶ × 7² ≡ 1⁵⁰⁶ × 49 ≡ 49 (mod 100).\n- Vậy hai chữ số tận cùng của 7²⁰²⁶ là 49.\n\n**Đáp số: 49.**"
