      "questionVi": "Tích 125! = 1 × 2 × 3 × ... × 125 có tận cùng bằng bao nhiêu chữ số 0 liên tiếp?",
      "questionEn": "How many consecutive zeros are there at the end of the product 125! = 1 × 2 × 3 × ... × 125?",
      "image": null,
      "answer": "31",
