      "questionVi": "Như hình vẽ bên dưới, P là một điểm bất kỳ nằm bên trong hình bình hành ABCD. Biết diện tích các tam giác PAB, PCD và PBC lần lượt là 24 cm², 46 cm² và 35 cm². Hãy tính diện tích của tam giác PAD theo cm².",
      "questionEn": "As shown in the figure, P is an arbitrary point inside parallelogram ABCD. The areas of triangles PAB, PCD and PBC are 24 cm², 46 cm² and 35 cm² respectively. Find the area of triangle PAD in cm².",
