      "categoryEn": "Geometry",
      "categoryId": "geometry",
      "questionVi": "Tính tổng số đo của 6 góc tại các đỉnh của ngôi sao 6 cánh dưới đây theo độ.",
      "questionEn": "Find the sum of the 6 marked angles at the vertices of the 6-pointed star (hexagram) shown below, in degrees.",
      "image": "images/practice_de1/q17_hexagram.png",
      "answer": "360",
      "acceptableAnswers": [
        "360"
      ],
      "unit": "",
      "hint": "Phân rã đa giác và tổng các góc trong tam giác.",
      "solution": "**Phương pháp: Phân rã đa giác và tổng các góc trong tam giác.**\n\n- Quan sát cấu tạo của ngôi sao 6 cánh được tạo thành từ hai tam giác lớn lồng vào nhau: tam giác ABC (hướng lên) và tam giác DEF (hướng xuống).\n- Sáu góc cần tính chính là 6 góc tại các đỉnh của hai tam giác này:\n  + Ba góc của tam giác ABC có tổng bằng: ∠A + ∠B + ∠C = 180°.\n  + Ba góc của tam giác DEF có tổng bằng: ∠D + ∠E + ∠F = 180°.\n- Do đó, tổng số đo của cả 6 góc tại đỉnh là:\n  (∠A + ∠B + ∠C) + (∠D + ∠E + ∠F) = 180° + 180° = 360°.\n- Vậy tổng số đo 6 góc là 360°.\n\n**Đáp số: 360.**"
