      "questionVi": "Một khối lập phương kích thước 4×4×4 được ghép từ 64 khối lập phương nhỏ cạnh 1×1×1. Người ta sơn màu đỏ lên toàn bộ 6 mặt ngoài của khối lập phương lớn, rồi tháo rời thành các khối lập phương nhỏ. Hỏi có bao nhiêu khối lập phương nhỏ có đúng 2 mặt được sơn màu đỏ?",
      "questionEn": "A solid cube of size 4×4×4 is made by gluing 64 identical 1×1×1 small cubes together. The exterior of the large cube is painted red on all 6 faces, and then disassembled back into small cubes. How many small cubes have exactly 2 faces painted red?",
