      "solution": "**Phương pháp: Phân loại vị trí các khối lập phương nhỏ trong không gian 3D.**\n\n- Khối lập phương lớn có 12 cạnh, 8 đỉnh và 6 mặt:\n  + Các khối có đúng 3 mặt sơn nằm tại 8 đỉnh (gồm 8 khối).\n  + Các khối có đúng 2 mặt sơn nằm dọc trên 12 cạnh của khối lớn (không tính 2 khối ở 2 đầu đỉnh).\n- Mỗi cạnh của khối lớn có độ dài bằng 4 đơn vị, trừ đi 2 khối ở 2 đầu đỉnh, trên mỗi cạnh còn lại:\n  4 – 2 = 2 (khối).\n- Vì khối lập phương có tất cả 12 cạnh nên tổng số khối có đúng 2 mặt sơn đỏ là:\n  12 × 2 = 24 (khối).\n\n**Đáp số: 24.**"
