      "questionVi": "Một tứ giác MNPQ được vẽ trên lưới ô vuông với mỗi ô vuông nhỏ có diện tích 1 cm², các đỉnh nằm tại các nút lưới M(1, 1), N(6, 2), P(5, 5) và Q(2, 4). Tính diện tích tứ giác MNPQ theo cm².",
      "questionEn": "A quadrilateral MNPQ is drawn on a square grid where each small square has an area of 1 cm², with vertices at grid points M(1, 1), N(6, 2), P(5, 5), and Q(2, 4). Find the area of quadrilateral MNPQ in cm².",
