      "solution": "**Phương pháp: Phương pháp bao hình chữ nhật và trừ diện tích phần bù (hoặc định lý Pick).**\n\n- Vẽ hình chữ nhật bao quanh tứ giác MNPQ với các cạnh song song với các đường lưới:\n  + Tọa độ cực trị: x từ 1 đến 6 (chiều dài = 6 – 1 = 5 cm); y từ 1 đến 5 (chiều rộng = 5 – 1 = 4 cm).\n  + Diện tích hình chữ nhật bao quanh là: S_hcn = 5 × 4 = 20 (cm²).\n- Diện tích tứ giác MNPQ bằng diện tích hình chữ nhật bao quanh trừ đi 4 tam giác vuông ở 4 góc:\n  + Góc dưới phải: tam giác có 2 cạnh góc vuông dài 5 và 1 => S₁ = 5 × 1 : 2 = 2.5 (cm²).\n  + Góc trên phải: tam giác có 2 cạnh góc vuông dài 1 và 3 => S₂ = 1 × 3 : 2 = 1.5 (cm²).\n  + Góc trên trái: tam giác có 2 cạnh góc vuông dài 3 và 1 => S₃ = 3 × 1 : 2 = 1.5 (cm²).\n  + Góc dưới trái: tam giác có 2 cạnh góc vuông dài 1 và 3 => S₄ = 1 × 3 : 2 = 1.5 (cm²).\n- Tổng diện tích 4 tam giác góc là:\n  S_phụ = 2.5 + 1.5 + 1.5 + 2.5 = 8 (cm²).\n- Diện tích tứ giác MNPQ là:\n  S(MNPQ) = 20 – 8 = 12 (cm²).\n\n**Đáp số: 12.**"
