      "hint": "Sai phân triệt tiêu phân số.",
      "solution": "**Phương pháp: Sai phân triệt tiêu phân số.**\n\n- Khoảng cách giữa hai thừa số ở mỗi mẫu số là: 7 – 3 = 11 – 7 = ... = 4.\n- Nhân cả biểu thức với 4, ta được:\n  4 × S = 4/(3×7) + 4/(7×11) + ... + 4/(39×43)\n  4 × S = (1/3 – 1/7) + (1/7 – 1/11) + ... + (1/39 – 1/43)\n- Triệt tiêu các phân số đối nhau ở giữa:\n  4 × S = 1/3 – 1/43 = (43 – 3) / (3 × 43) = 40 / 129\n- Suy ra:\n  S = (40 / 129) : 4 = 10 / 129.\n\n**Đáp số: 10/129.**"
