      "hint": "Nhân dồn cơ số tính tổng cấp số nhân.",
      "solution": "**Phương pháp: Nhân dồn cơ số tính tổng cấp số nhân.**\n\n- Ta có: S = 4 + 4² + 4³ + 4⁴ + 4⁵ + 4⁶.\n- Nhân cả hai vế với 4:\n  4 × S = 4² + 4³ + 4⁴ + 4⁵ + 4⁶ + 4⁷.\n- Trừ vế theo vế:\n  4 × S – S = 4⁷ – 4\n  3 × S = 4⁷ – 4.\n- Tính 4⁷: 4⁷ = 2¹⁴ = 16384.\n- Suy ra:\n  3 × S = 16384 – 4 = 16380\n  S = 16380 : 3 = 5460.\n\n**Đáp số: 5460.**"
