      "solution": "**Phương pháp: Hàm phi Euler φ(n).**\n\n- Phân tích 150 ra thừa số nguyên tố:\n  150 = 2 × 3 × 5².\n- Các ước nguyên tố của 150 là 2, 3 và 5.\n- Áp dụng công thức hàm phi Euler:\n  φ(150) = 150 × (1 – 1/2) × (1 – 1/3) × (1 – 1/5)\n  φ(150) = 150 × (1/2) × (2/3) × (4/5) = 150 × (4/15) = 40.\n- Vậy có 40 số nguyên dương thỏa mãn.\n\n**Đáp số: 40.**"
