      "solution": "**Phương pháp: Công thức Legendre.**\n\n- Số chữ số 0 tận cùng của 150! bằng số mũ của thừa số nguyên tố 5 trong khai triển của 150!.\n- Áp dụng công thức Legendre:\n  E₅(150!) = [150 / 5] + [150 / 25] + [150 / 125]\n  E₅(150!) = 30 + 6 + 1 = 37.\n- Vậy tích 150! có đúng 37 chữ số 0 tận cùng.\n\n**Đáp số: 37.**"
