      "questionVi": "Như hình vẽ bên dưới, P là một điểm bất kỳ nằm bên trong hình chữ nhật ABCD có diện tích 80 cm². Diện tích tam giác PAB và PBC lần lượt là 16 cm² và 22 cm². Hãy tính diện tích của tam giác PAD theo cm².",
