      "solution": "**Phương pháp: Bổ đề diện tích điểm trong hình chữ nhật.**\n\n- Vì hình chữ nhật cũng là một hình bình hành, nên với mọi điểm P nằm trong hình chữ nhật ABCD, ta luôn có:\n  S(PAB) + S(PCD) = S(PAD) + S(PBC) = 1/2 × S(ABCD).\n- Theo đề bài, diện tích hình chữ nhật là 80 cm²:\n  S(PAD) + S(PBC) = 1/2 × 80 = 40 (cm²).\n- Đã biết S(PBC) = 22 cm², suy ra:\n  S(PAD) = 40 – 22 = 18 (cm²).\n\n**Đáp số: 18.**"
