      "questionVi": "Một khối lập phương lớn cạnh 5 cm được ghép từ 125 khối lập phương nhỏ 1×1×1 cm. Người ta sơn màu xanh lên toàn bộ 6 mặt ngoài của khối lớn rồi tháo rời ra. Hỏi có bao nhiêu khối lập phương nhỏ có đúng 1 mặt được sơn màu xanh?",
      "questionEn": "A large cube of side length 5 cm is made of 125 small cubes of size 1×1×1 cm. The outside of the large cube is painted blue on all 6 faces, and then taken apart. How many small cubes have exactly 1 face painted blue?",
      "image": null,
      "answer": "54",
