      "questionVi": "Theo sơ đồ mạng lưới dưới đây, có bao nhiêu đường đi ngắn nhất từ điểm A đến điểm B mà bắt buộc phải đi qua điểm C?",
      "questionEn": "As shown in the grid below, how many shortest paths are there from point A to point B that pass through point C?",
      "image": "images/practice_de2/q23_grid_path.png",
      "answer": "90",
      "acceptableAnswers": [
        "90"
      ],
      "unit": "",
      "hint": "Quy tắc nhân và tổ hợp đường đi trên lưới.",
      "solution": "**Phương pháp: Quy tắc nhân và tổ hợp đường đi trên lưới.**\n\n- Quá trình di chuyển chia thành 2 chặng độc lập:\n  + Chặng 1: Từ A(0, 0) đến C(2, 2). Cần đi 2 bước sang phải và 2 bước lên trên (tổng 4 bước).\n    Số đường đi là: C(4, 2) = (4 × 3) / (2 × 1) = 6 (đường).\n  + Chặng 2: Từ C(2, 2) đến B(6, 4). Cần đi 6 – 2 = 4 bước sang phải và 4 – 2 = 2 bước lên trên (tổng 6 bước).\n    Số đường đi là: C(6, 2) = (6 × 5) / (2 × 1) = 15 (đường).\n- Áp dụng quy tắc nhân, tổng số đường đi ngắn nhất thỏa mãn là:\n  6 × 15 = 90 (đường đi).\n\n**Đáp số: 90.**"
