      "solution": "**Phương pháp: Phương pháp vách ngăn (Stars and Bars).**\n\n- Xếp 14 cái kẹo thành một hàng dọc, giữa chúng có 14 – 1 = 13 khoảng trống.\n- Để chia cho 5 bạn sao cho mỗi bạn có ít nhất 1 cái kẹo, ta đặt 5 – 1 = 4 vách ngăn vào 4 khoảng trống trong số 13 khoảng trống đó.\n- Số cách đặt vách ngăn là:\n  C(13, 4) = (13 × 12 × 11 × 10) / (4 × 3 × 2 × 1) = 17160 / 24 = 715 (cách).\n- Vậy có 715 cách chia kẹo.\n\n**Đáp số: 715.**"
