      "hint": "Sai phân triệt tiêu phân số.",
      "solution": "**Phương pháp: Sai phân triệt tiêu phân số.**\n\n- Khoảng cách giữa hai thừa số ở mỗi mẫu số là: 4 – 1 = 7 – 4 = ... = 3.\n- Nhân biểu thức với 3:\n  3 × S = 3/(1×4) + 3/(4×7) + ... + 3/(28×31)\n  3 × S = (1/1 – 1/4) + (1/4 – 1/7) + ... + (1/28 – 1/31)\n- Triệt tiêu các hạng tử đối dấu ở giữa:\n  3 × S = 1 – 1/31 = 30/31\n- Suy ra:\n  S = (30/31) : 3 = 10/31.\n\n**Đáp số: 10/31.**"
