      "solution": "**Phương pháp: Chuyển số thập phân tuần hoàn thành phân số tối giản.**\n\n- Đặt x = 0.4161616...\n- Nhân với 10 và 1000:\n  10x = 4.161616...\n  1000x = 416.161616...\n- Trừ hai vế:\n  1000x – 10x = 416 – 4 = 412\n  990x = 412\n  x = 412 / 990.\n- Rút gọn cho ƯCLN(412, 990) = 2:\n  x = 206 / 495.\n\n**Đáp số: 206/495.**"
