      "solution": "**Phương pháp: Tổng cấp số nhân nhân dồn cơ số.**\n\n- Ta có: S = 5 + 5² + 5³ + 5⁴ + 5⁵.\n- Nhân cả hai vế với 5:\n  5 × S = 5² + 5³ + 5⁴ + 5⁵ + 5⁶.\n- Lấy hiệu:\n  5 × S – S = 5⁶ – 5\n  4 × S = 15625 – 5 = 15620\n  S = 15620 : 4 = 3905.\n\n**Đáp số: 3905.**"
