      "hint": "Chu kỳ hai chữ số tận cùng modulo 100.",
      "solution": "**Phương pháp: Chu kỳ hai chữ số tận cùng modulo 100.**\n\n- Xét các lũy thừa đặc biệt của cơ số 2:\n  2¹⁰ = 1024 ≡ 24 (mod 100).\n  2²⁰ = (2¹⁰)² ≡ 24² = 576 ≡ 76 (mod 100).\n- Nhận xét tính chất bất biến: 76 × 76 = 5776 ≡ 76 (mod 100), do đó 76^k luôn tận cùng là 76 với mọi số nguyên dương k.\n- Ta phân tích số mũ 2026:\n  2026 = 20 × 101 + 6.\n- Do đó:\n  2²⁰²⁶ = (2²⁰)¹⁰¹ × 2⁶ ≡ 76¹⁰¹ × 64 ≡ 76 × 64 (mod 100).\n- Tính tích:\n  76 × 64 = 4864 ≡ 64 (mod 100).\n- Vậy hai chữ số tận cùng của 2²⁰²⁶ là 64.\n\n**Đáp số: 64.**"
