      "unit": "",
      "hint": "Phân tích thừa số nguyên tố và công thức tính tổng các ước số.",
      "solution": "**Phương pháp: Phân tích thừa số nguyên tố và công thức tính tổng các ước số.**\n\n- Phân tích số 360 ra thừa số nguyên tố:\n  360 = 36 × 10 = (2² × 3²) × (2 × 5) = 2³ × 3² × 5.\n- Công thức tổng các ước: Nếu N = p₁^a × p₂^b × p₃^c thì tổng các ước σ(N) là:\n  σ(N) = (1 + p₁ + ... + p₁^a) × (1 + p₂ + ... + p₂^b) × (1 + p₃ + ... + p₃^c).\n- Áp dụng với số 360:\n  σ(360) = (1 + 2 + 4 + 8) × (1 + 3 + 9) × (1 + 5)\n  σ(360) = 15 × 13 × 6 = 195 × 6 = 1170.\n\n**Đáp số: 1170.**"
