      "hint": "Hàm phi Euler φ(n).",
      "solution": "**Phương pháp: Hàm phi Euler φ(n).**\n\n- Phân tích 200 ra thừa số nguyên tố: 200 = 2³ × 5².\n- Các ước nguyên tố của 200 là 2 và 5.\n- Áp dụng công thức Euler:\n  φ(200) = 200 × (1 – 1/2) × (1 – 1/5) = 200 × (1/2) × (4/5) = 80.\n- Vậy có 80 số thỏa mãn.\n\n**Đáp số: 80.**"
