      "solution": "**Phương pháp: Công thức tính tổng các góc trong của đa giác lồi n cạnh.**\n\n- Một đa giác lồi n cạnh có thể chia thành (n – 2) tam giác không chồng chéo bằng các đường chéo xuất phát từ một đỉnh.\n- Tổng số đo các góc trong của đa giác n cạnh là: (n – 2) × 180°.\n- Áp dụng với bát giác (n = 8):\n  Tổng số đo các góc = (8 – 2) × 180° = 6 × 180° = 1080°.\n\n**Đáp số: 1080.**"
