      "categoryEn": "Geometry",
      "categoryId": "geometry",
      "questionVi": "Một khối lập phương kích thước 4×4×4 được ghép từ 64 khối lập phương nhỏ cạnh 1×1×1. Người ta sơn màu đỏ lên toàn bộ 6 mặt ngoài của khối lớn rồi tháo rời ra. Hỏi có bao nhiêu khối lập phương nhỏ không có mặt nào được sơn màu đỏ?",
      "questionEn": "A solid cube of size 4×4×4 is made by gluing 64 small cubes of 1×1×1 together. The outside of the large cube is painted red on all 6 faces, and then taken apart. How many small cubes have NO face painted red?",
