      "hint": "Chuyển số thập phân tuần hoàn thành phân số tối giản.",
      "solution": "**Phương pháp: Chuyển số thập phân tuần hoàn thành phân số tối giản.**\n\n- Đặt x = 0.123123123...\n- Chu kỳ tuần hoàn gồm 3 chữ số (123), nhân cả hai vế với 1000:\n  1000x = 123.123123123...\n- Lấy hiệu hai đẳng thức:\n  1000x – x = 123\n  999x = 123\n  x = 123 / 999.\n- Rút gọn cho ƯCLN(123, 999) = 3:\n  x = (123 : 3) / (999 : 3) = 41 / 333.\n\n**Đáp số: 41/333.**"
