      "questionVi": "Tính tổng: S = 1 + 3 + 3² + 3³ + 3⁴ + 3⁵ + 3⁶ + 3⁷.",
      "questionEn": "Find the sum: S = 1 + 3 + 3² + 3³ + 3⁴ + 3⁵ + 3⁶ + 3⁷.",
      "image": null,
      "answer": "3280",
      "acceptableAnswers": [
        "3280"
      ],
      "unit": "",
      "hint": "Tổng cấp số nhân nhân dồn cơ số.",
      "solution": "**Phương pháp: Tổng cấp số nhân nhân dồn cơ số.**\n\n- Ta có: S = 1 + 3 + 3² + ... + 3⁷.\n- Nhân cả hai vế với cơ số 3:\n  3 × S = 3 + 3² + 3³ + ... + 3⁷ + 3⁸.\n- Lấy hiệu:\n  3 × S – S = 3⁸ – 1\n  2 × S = 3⁸ – 1.\n- Tính lũy thừa: 3⁴ = 81  =>  3⁸ = 81² = 6561.\n- Suy ra:\n  2 × S = 6561 – 1 = 6560\n  S = 6560 : 2 = 3280.\n\n**Đáp số: 3280.**"
