      "unit": "",
      "hint": "Chu kỳ chữ số tận cùng của lũy thừa.",
      "solution": "**Phương pháp: Chu kỳ chữ số tận cùng của lũy thừa.**\n\n- Chữ số tận cùng của mỗi số hạng:\n  + Số thứ nhất: 2026²⁰²⁶ có tận cùng là 6 (vì số tận cùng bằng 6 nâng lên lũy thừa nguyên dương bất kỳ luôn tận cùng bằng 6).\n  + Số thứ hai: 2027²⁰²⁷ có tận cùng giống 7²⁰²⁷.\n    Chu kỳ tận cùng của cơ số 7 là 4 (7, 9, 3, 1). Vì 2027 chia 4 dư 3 nên 7²⁰²⁷ có tận cùng giống 7³ = 343, tức là tận cùng bằng 3.\n  + Số thứ ba: 2028²⁰²⁸ có tận cùng giống 8²⁰²⁸.\n    Chu kỳ tận cùng của cơ số 8 là 4 (8, 4, 2, 6). Vì 2028 chia hết cho 4 nên 8²⁰²⁸ có tận cùng giống 8⁴, tức là tận cùng bằng 6.\n- Chữ số tận cùng của tổng bằng chữ số tận cùng của: 6 + 3 + 6 = 15, tức là chữ số 5.\n\n**Đáp số: 5.**"
