      "questionVi": "Tích 75! = 1 × 2 × 3 × ... × 75 có tận cùng bằng bao nhiêu chữ số 0 liên tiếp?",
      "questionEn": "How many consecutive zeros are there at the end of the product 75! = 1 × 2 × 3 × ... × 75?",
      "image": null,
      "answer": "18",
      "acceptableAnswers": [
        "18"
      ],
      "unit": "",
      "hint": "Công thức Legendre.",
      "solution": "**Phương pháp: Công thức Legendre.**\n\n- Áp dụng công thức Legendre tính số mũ của thừa số nguyên tố 5 trong 75!:\n  E₅(75!) = [75 / 5] + [75 / 25]\n  E₅(75!) = 15 + 3 = 18.\n- Vậy tích 75! có đúng 18 chữ số 0 tận cùng liên tiếp.\n\n**Đáp số: 18.**"
