      "questionVi": "Như hình vẽ bên dưới, ABCD là hình vuông cạnh 14 cm. Một hình tròn được vẽ nội tiếp bên trong hình vuông. Hãy tính tổng diện tích của phần tô đậm (4 góc nằm giữa hình vuông và hình tròn) theo cm². (Lấy π = 22/7).",
      "questionEn": "As shown in the figure, ABCD is a square of side length 14 cm. A circle is inscribed inside the square. Find the total area of the shaded region (the 4 corners between the square and the circle) in cm². (Take π = 22/7).",
