      "hint": "Hiệu diện tích giữa hình vuông và hình tròn nội tiếp.",
      "solution": "**Phương pháp: Hiệu diện tích giữa hình vuông và hình tròn nội tiếp.**\n\n- Diện tích của hình vuông ABCD là:\n  S_hv = a² = 14 × 14 = 196 (cm²).\n- Bán kính của đường tròn nội tiếp hình vuông bằng một nửa cạnh hình vuông:\n  R = 14 : 2 = 7 (cm).\n- Diện tích của hình tròn nội tiếp là:\n  S_tròn = π × R² = (22 / 7) × 7² = 22 × 7 = 154 (cm²).\n- Diện tích phần tô đậm ở 4 góc là:\n  S_tô = S_hv – S_tròn = 196 – 154 = 42 (cm²).\n\n**Đáp số: 42.**"
