      "solution": "**Phương pháp: Phân loại vị trí các khối lập phương trong không gian 3D.**\n\n- Khối có \"ít nhất 2 mặt sơn xanh\" bao gồm: các khối có đúng 2 mặt sơn và các khối có đúng 3 mặt sơn.\n  + Các khối có đúng 3 mặt sơn nằm tại 8 đỉnh của khối lớn => có đúng 8 khối.\n  + Các khối có đúng 2 mặt sơn nằm dọc trên 12 cạnh của khối lớn (trừ 2 khối đỉnh ở 2 đầu cạnh):\n    Mỗi cạnh có: 5 – 2 = 3 (khối).\n    12 cạnh có: 12 × 3 = 36 (khối).\n- Tổng số khối có ít nhất 2 mặt được sơn màu xanh là:\n  8 + 36 = 44 (khối).\n\n**Đáp số: 44.**"
