      "solution": "**Phương pháp: Công thức diện tích hình thang trên hệ tọa độ lưới.**\n\n- Đáy dưới AB nằm ngang trên đường y = 1 có độ dài: 7 – 1 = 6 (cm).\n- Đáy trên CD nằm ngang trên đường y = 5 có độ dài: 5 – 2 = 3 (cm).\n- Chiều cao h của hình thang là khoảng cách thẳng đứng giữa hai đáy y = 5 và y = 1:\n  h = 5 – 1 = 4 (cm).\n- Diện tích của hình thang ABCD là:\n  S = (AB + CD) × h : 2 = (6 + 3) × 4 : 2 = 9 × 2 = 18 (cm²).\n\n**Đáp số: 18.**"
