      "hint": "Sai phân triệt tiêu phân số.",
      "solution": "**Phương pháp: Sai phân triệt tiêu phân số.**\n\n- Khoảng cách giữa hai thừa số ở mỗi mẫu số là: 3 – 1 = 5 – 3 = ... = 2, đúng bằng tử số.\n- Áp dụng trực tiếp công thức sai phân: 2 / [n × (n + 2)] = 1/n – 1/(n + 2).\n- Viết lại biểu thức:\n  S = (1/1 – 1/3) + (1/3 – 1/5) + (1/5 – 1/7) + ... + (1/19 – 1/21)\n- Triệt tiêu các phân số ở giữa:\n  S = 1 – 1/21 = 20/21.\n\n**Đáp số: 20/21.**"
