      "categoryEn": "Arithmetic",
      "categoryId": "arithmetic",
      "questionVi": "Tính tổng: S = 1 + 2 + 2² + 2³ + ... + 2¹².",
      "questionEn": "Find the sum: S = 1 + 2 + 2² + 2³ + ... + 2¹².",
      "image": null,
      "answer": "8191",
      "acceptableAnswers": [
        "8191"
      ],
      "unit": "",
      "hint": "Tổng cấp số nhân cơ số 2.",
      "solution": "**Phương pháp: Tổng cấp số nhân cơ số 2.**\n\n- Ta có: S = 1 + 2 + 2² + ... + 2¹².\n- Nhân cả hai vế với 2:\n  2 × S = 2 + 2² + 2³ + ... + 2¹² + 2¹³.\n- Trừ vế theo vế:\n  2 × S – S = 2¹³ – 1\n  S = 2¹³ – 1.\n- Tính 2¹³: 2¹⁰ = 1024  =>  2¹³ = 1024 × 8 = 8192.\n- Suy ra:\n  S = 8192 – 1 = 8191.\n\n**Đáp số: 8191.**"
