      "questionVi": "Quy ước phép toán a * b = 4a + 3b – 1. Biết rằng (2 * x) * 3 = 84, hãy tìm giá trị của x.",
      "questionEn": "Define the operation a * b = 4a + 3b – 1. If (2 * x) * 3 = 84, find the value of x.",
      "image": null,
      "answer": "4",
      "acceptableAnswers": [
        "4"
      ],
      "unit": "",
      "hint": "Phép toán định nghĩa mới và tính ngược ẩn số.",
      "solution": "**Phương pháp: Phép toán định nghĩa mới và tính ngược ẩn số.**\n\n- Đặt Y = 2 * x.\n- Theo quy ước: Y * 3 = 4 × Y + 3 × 3 – 1 = 4 × Y + 9 – 1 = 4 × Y + 8.\n- Theo đề bài:\n  4 × Y + 8 = 84  =>  4 × Y = 84 – 8 = 76  =>  Y = 76 : 4 = 19.\n- Thay lại Y = 2 * x:\n  2 * x = 4 × 2 + 3 × x – 1 = 8 + 3 × x – 1 = 3 × x + 7.\n- Vì Y = 19 nên:\n  3 × x + 7 = 19  =>  3 × x = 12  =>  x = 4.\n\n**Đáp số: 4.**"
