      "solution": "**Phương pháp: Phân tích thừa số nguyên tố và công thức số ước.**\n\n- Phân tích 720 ra thừa số nguyên tố:\n  720 = 72 × 10 = (2³ × 3²) × (2 × 5) = 2⁴ × 3² × 5¹.\n- Áp dụng công thức tính số lượng ước nguyên dương:\n  d(720) = (4 + 1) × (2 + 1) × (1 + 1) = 5 × 3 × 2 = 30 (ước).\n\n**Đáp số: 30.**"
