      "questionVi": "Có bao nhiêu số nguyên dương nhỏ hơn 240 và nguyên tố cùng nhau với 240?",
      "questionEn": "How many positive integers less than 240 are relatively prime to 240?",
      "image": null,
      "answer": "64",
      "acceptableAnswers": [
        "64"
      ],
      "unit": "",
      "hint": "Hàm phi Euler φ(n).",
      "solution": "**Phương pháp: Hàm phi Euler φ(n).**\n\n- Phân tích 240 ra thừa số nguyên tố: 240 = 2⁴ × 3 × 5.\n- Các ước nguyên tố của 240 là 2, 3 và 5.\n- Áp dụng công thức Euler:\n  φ(240) = 240 × (1 – 1/2) × (1 – 1/3) × (1 – 1/5)\n  φ(240) = 240 × (1/2) × (2/3) × (4/5) = 240 × (4/15) = 64.\n- Vậy có 64 số thỏa mãn.\n\n**Đáp số: 64.**"
