      "questionVi": "Tích 250! = 1 × 2 × 3 × ... × 250 có tận cùng bằng bao nhiêu chữ số 0 liên tiếp?",
      "questionEn": "How many consecutive zeros are there at the end of the product 250! = 1 × 2 × 3 × ... × 250?",
      "image": null,
      "answer": "62",
      "acceptableAnswers": [
        "62"
      ],
      "unit": "",
      "hint": "Công thức Legendre.",
      "solution": "**Phương pháp: Công thức Legendre.**\n\n- Áp dụng công thức Legendre tính số mũ của thừa số 5 trong 250!:\n  E₅(250!) = [250 / 5] + [250 / 25] + [250 / 125]\n  E₅(250!) = 50 + 10 + 2 = 62.\n- Vậy tích 250! có đúng 62 chữ số 0 tận cùng liên tiếp.\n\n**Đáp số: 62.**"
