      "questionVi": "Một khối lập phương kích thước 6×6×6 được ghép từ 216 khối lập phương nhỏ 1×1×1. Người ta sơn màu vàng lên toàn bộ 6 mặt ngoài của khối lớn rồi tháo rời ra. Hỏi có bao nhiêu khối lập phương nhỏ có đúng 2 mặt được sơn màu vàng?",
      "questionEn": "A solid cube of size 6×6×6 is made of 216 small cubes of 1×1×1. All 6 faces of the large cube are painted yellow, and then it is disassembled into small cubes. How many small cubes have EXACTLY 2 faces painted yellow?",
