      "solution": "**Phương pháp: Phân loại vị trí các khối lập phương trong không gian 3D.**\n\n- Các khối lập phương nhỏ có đúng 2 mặt sơn vàng nằm dọc trên 12 cạnh của khối lớn (không tính 2 khối đỉnh ở 2 đầu cạnh).\n- Mỗi cạnh của khối lập phương lớn có độ dài 6 đơn vị, trừ đi 2 khối đỉnh ở 2 đầu, trên mỗi cạnh còn lại:\n  6 – 2 = 4 (khối).\n- Vì khối lập phương có tất cả 12 cạnh nên tổng số khối có đúng 2 mặt sơn vàng là:\n  12 × 4 = 48 (khối).\n\n**Đáp số: 48.**"
