      "questionVi": "Một tứ giác ABCD được vẽ trên lưới ô vuông với mỗi ô vuông nhỏ có diện tích 1 cm², các đỉnh nằm tại các nút lưới A(1, 2), B(6, 1), C(7, 5) và D(2, 6). Tính diện tích tứ giác ABCD theo cm².",
      "questionEn": "A quadrilateral ABCD is drawn on a square grid where each small square has an area of 1 cm², with vertices at A(1, 2), B(6, 1), C(7, 5), and D(2, 6). Find the area of quadrilateral ABCD in cm².",
