      "solution": "**Phương pháp: Phương pháp bao hình chữ nhật và trừ diện tích phần bù.**\n\n- Dựng hình chữ nhật bao quanh tứ giác ABCD:\n  + Chiều ngang: từ x = 1 đến x = 7 => Chiều dài = 7 – 1 = 6 cm.\n  + Chiều dọc: từ y = 1 đến y = 6 => Chiều rộng = 6 – 1 = 5 cm.\n  + Diện tích hình chữ nhật bao quanh là: S_bao = 6 × 5 = 30 (cm²).\n- Diện tích tứ giác ABCD bằng diện tích hình chữ nhật bao quanh trừ đi 4 tam giác vuông ở 4 góc:\n  + Góc dưới trái: tam giác nối (1,2) và (6,1) có đáy = 5, cao = 1 => S₁ = 5 × 1 : 2 = 2.5 (cm²).\n  + Góc dưới phải: tam giác nối (6,1) và (7,5) có đáy = 1, cao = 4 => S₂ = 1 × 4 : 2 = 2 (cm²).\n  + Góc trên phải: tam giác nối (7,5) và (2,6) có đáy = 5, cao = 1 => S₃ = 5 × 1 : 2 = 2.5 (cm²).\n  + Góc trên trái: tam giác nối (2,6) và (1,2) có đáy = 1, cao = 4 => S₄ = 1 × 4 : 2 = 2 (cm²).\n- Tổng diện tích 4 tam giác góc là: 2.5 + 2 + 2.5 + 2 = 9 (cm²).\n- Diện tích tứ giác ABCD là:\n  S(ABCD) = 30 – 9 = 21 (cm²).\n\n**Đáp số: 21.**"
