      "questionVi": "Lúc 6 giờ đúng, kim giờ và kim phút của đồng hồ tạo thành một đường thẳng (ngược chiều nhau 180°). Hỏi vào thời điểm nào sau 6 giờ thì hai kim lại tạo thành một đường thẳng lần tiếp theo?",
      "questionEn": "At 6:00, the hour hand and minute hand of a clock point in opposite directions (form a straight line of 180°). At what time after 6:00 will the two hands point in opposite directions again?",
