      "solution": "**Phương pháp: Tổ hợp chọn chập 4 của 10 phần tử C(10, 4).**\n\n- Chọn 4 bạn trong số 10 bạn không phân biệt thứ tự là một tổ hợp chập 4 của 10 phần tử.\n- Áp dụng công thức tổ hợp:\n  C(10, 4) = (10 × 9 × 8 × 7) / (4 × 3 × 2 × 1) = 5040 / 24 = 210 (cách).\n- Vậy có tất cả 210 cách chọn ban cán sự.\n\n**Đáp số: 210.**"
