      "unit": "",
      "hint": "Sai phân triệt tiêu phân số.",
      "solution": "**Phương pháp: Sai phân triệt tiêu phân số.**\n\n- Khoảng cách giữa hai thừa số ở mỗi mẫu số là: 9 – 4 = 14 – 9 = ... = 5.\n- Nhân cả biểu thức với 5:\n  5 × S = 5/(4×9) + 5/(9×14) + ... + 5/(44×49)\n  5 × S = (1/4 – 1/9) + (1/9 – 1/14) + ... + (1/44 – 1/49)\n- Triệt tiêu các phân số ở giữa:\n  5 × S = 1/4 – 1/49 = (49 – 4) / (4 × 49) = 45 / 196\n- Suy ra:\n  S = (45 / 196) : 5 = 9 / 196.\n\n**Đáp số: 9/196.**"
