      "hint": "Chuyển số thập phân tuần hoàn thành phân số tối giản.",
      "solution": "**Phương pháp: Chuyển số thập phân tuần hoàn thành phân số tối giản.**\n\n- Đặt x = 0.8333...\n- Nhân x với 10 và 100:\n  10x = 8.333...\n  100x = 83.333...\n- Trừ vế theo vế:\n  100x – 10x = 83 – 8 = 75\n  90x = 75\n  x = 75 / 90.\n- Rút gọn cho ƯCLN(75, 90) = 15:\n  x = 5 / 6.\n\n**Đáp số: 5/6.**"
