      "categoryId": "number_theory",
      "questionVi": "Có bao nhiêu số nguyên dương nhỏ hơn 300 và nguyên tố cùng nhau với 300?",
      "questionEn": "How many positive integers less than 300 are relatively prime to 300?",
      "image": null,
      "answer": "80",
      "acceptableAnswers": [
        "80"
      ],
      "unit": "",
      "hint": "Hàm phi Euler φ(n).",
      "solution": "**Phương pháp: Hàm phi Euler φ(n).**\n\n- Phân tích 300 ra thừa số nguyên tố: 300 = 3 × 100 = 2² × 3 × 5².\n- Các ước nguyên tố của 300 là 2, 3 và 5.\n- Áp dụng công thức Euler:\n  φ(300) = 300 × (1 – 1/2) × (1 – 1/3) × (1 – 1/5)\n  φ(300) = 300 × (1/2) × (2/3) × (4/5) = 300 × (4/15) = 80.\n- Vậy có 80 số thỏa mãn.\n\n**Đáp số: 80.**"
