      "questionVi": "Tích 500! = 1 × 2 × 3 × ... × 500 có tận cùng bằng bao nhiêu chữ số 0 liên tiếp?",
      "questionEn": "How many consecutive zeros are there at the end of the product 500! = 1 × 2 × 3 × ... × 500?",
      "image": null,
      "answer": "124",
      "acceptableAnswers": [
        "124"
      ],
      "unit": "",
      "hint": "Công thức Legendre.",
      "solution": "**Phương pháp: Công thức Legendre.**\n\n- Áp dụng công thức Legendre tính số mũ của thừa số 5 trong 500!:\n  E₅(500!) = [500 / 5] + [500 / 25] + [500 / 125]\n  E₅(500!) = 100 + 20 + 4 = 124.\n- Vậy tích 500! có đúng 124 chữ số 0 tận cùng liên tiếp.\n\n**Đáp số: 124.**"
