      "categoryId": "geometry",
      "questionVi": "Một tứ giác ABCD được vẽ trên lưới ô vuông với mỗi ô vuông nhỏ có diện tích 1 cm², các đỉnh nằm tại các nút lưới A(2, 1), B(7, 2), C(6, 6) và D(1, 4). Tính diện tích tứ giác ABCD theo cm².",
      "questionEn": "A quadrilateral ABCD is drawn on a square grid where each small square has an area of 1 cm², with vertices at A(2, 1), B(7, 2), C(6, 6), and D(1, 4). Find the area of quadrilateral ABCD in cm².",
