      "unit": "",
      "hint": "Phương pháp bao hình chữ nhật và trừ diện tích phần bù.",
      "solution": "**Phương pháp: Phương pháp bao hình chữ nhật và trừ diện tích phần bù.**\n\n- Dựng hình chữ nhật bao quanh tứ giác ABCD:\n  + Chiều ngang: từ x = 1 đến x = 7 => Chiều dài = 7 – 1 = 6 cm.\n  + Chiều dọc: từ y = 1 đến y = 6 => Chiều rộng = 6 – 1 = 5 cm.\n  + Diện tích hình chữ nhật bao quanh là: S_bao = 6 × 5 = 30 (cm²).\n- Trừ đi diện tích 4 tam giác vuông ở 4 góc:\n  + Góc dưới trái (nối (1,4) và (2,1)): S₁ = 1 × 3 : 2 = 1.5 (cm²).\n  + Góc dưới phải (nối (2,1) và (7,2)): S₂ = 5 × 1 : 2 = 2.5 (cm²).\n  + Góc trên phải (nối (7,2) và (6,6)): S₃ = 1 × 4 : 2 = 2 (cm²).\n  + Góc trên trái (nối (6,6) và (1,4)): S₄ = 5 × 2 : 2 = 5 (cm²).\n- Tổng diện tích 4 tam giác góc là: 1.5 + 2.5 + 2 + 5 = 11 (cm²).\n- Diện tích tứ giác ABCD là:\n  S(ABCD) = 30 – 11 = 19 (cm²).\n\n**Đáp số: 19.**"
