      "solution": "**Phương pháp: Hiệu vận tốc góc hai kim đồng hồ.**\n\n- Lúc 1 giờ đúng, kim phút chỉ số 12, kim giờ chỉ số 1 (cách nhau 5 khoảng phút, ứng với 30°).\n- Góc 90° tương ứng với 15 khoảng phút.\n- Kim phút phải vượt qua kim giờ để tạo thành góc 90° phía trước kim giờ.\n- Khoảng cách kim phút cần di chuyển là:\n  5 + 15 = 20 (khoảng phút).\n- Hiệu vận tốc giữa kim phút và kim giờ là: 1 – 1/12 = 11/12 (khoảng phút/phút).\n- Thời gian cần thiết là:\n  20 : (11/12) = 20 × 12 / 11 = 240 / 11 = 21 9/11 (phút).\n- Vậy thời điểm hai kim vuông góc là: 1 giờ 21 9/11 phút (hoặc 1:21 9/11).\n\n**Đáp số: 1:21 9/11.**"
