      "solution": "**Phương pháp: Quy tắc nhân và tổ hợp đường đi trên lưới.**\n\n- Quá trình di chuyển chia làm 2 chặng độc lập:\n  + Chặng 1: Từ A(0, 0) đến C(4, 2). Cần đi 4 bước sang phải và 2 bước lên trên (tổng 6 bước).\n    Số đường đi là: C(6, 2) = (6 × 5) / 2 = 15 (đường).\n  + Chặng 2: Từ C(4, 2) đến B(6, 4). Cần đi 6 – 4 = 2 bước sang phải và 4 – 2 = 2 bước lên trên (tổng 4 bước).\n    Số đường đi là: C(4, 2) = (4 × 3) / 2 = 6 (đường).\n- Áp dụng quy tắc nhân, tổng số đường đi ngắn nhất là:\n  15 × 6 = 90 (đường đi).\n\n**Đáp số: 90.**"
