      "solution": "**Phương pháp: Phương pháp vách ngăn (Stars and Bars).**\n\n- Xếp 13 chiếc bút chì thành một hàng ngang, giữa chúng có 13 – 1 = 12 khoảng trống.\n- Để chia cho 4 bạn sao cho mỗi bạn có ít nhất 1 chiếc, ta cần đặt 4 – 1 = 3 vách ngăn vào 3 khoảng trống trong số 12 khoảng trống đó.\n- Số cách đặt vách ngăn là:\n  C(12, 3) = (12 × 11 × 10) / (3 × 2 × 1) = 1320 / 6 = 220 (cách).\n- Vậy có 220 cách chia.\n\n**Đáp số: 220.**"
