      "solution": "**Phương pháp: Nguyên lý Dirichlet và xét trường hợp bất lợi nhất.**\n\n- Chỉ có màu đỏ (28 viên) và màu xanh dương (22 viên) là có đủ số lượng từ 16 viên trở lên.\n- Màu xanh lá cây (14 viên) và màu vàng (8 viên) đều có số lượng ít hơn 16 viên.\n- Xét tình huống xấu nhất (bất lợi nhất):\n  + Ta lấy hết sạch toàn bộ 8 viên bi màu vàng (chưa đủ 16 viên).\n  + Ta lấy hết sạch toàn bộ 14 viên bi màu xanh lá cây (chưa đủ 16 viên).\n  + Ta lấy tối đa 15 viên bi màu đỏ (thiếu đúng 1 viên để đạt 16).\n  + Ta lấy tối đa 15 viên bi màu xanh dương (thiếu đúng 1 viên để đạt 16).\n- Tổng số viên bi lấy ra trong trường hợp bất lợi nhất là:\n  8 + 14 + 15 + 15 = 52 (viên bi).\n- Lúc này trong hộp chỉ còn lại bi màu đỏ hoặc xanh dương. Khi lấy thêm đúng 1 viên bi nữa (viên thứ 53), viên bi này chắc chắn sẽ là bi đỏ hoặc bi xanh dương, nâng tổng số bi của màu đó lên đúng 15 + 1 = 16 viên.\n- Vậy số viên bi tối thiểu cần lấy ra là: 52 + 1 = 53 (viên bi).\n\n**Đáp số: 53.**"
